import json
from pathlib import Path
slides=[]
def add(topic,title,subtitle,pages,kind,**kwargs):
 slides.append(dict(topic=topic,title=title,subtitle=subtitle,pages=pages,kind=kind,**kwargs))
def c(title,text): return dict(title=title,text=text)
def q(question,answer,explanation,code=None):
 d=dict(question=question,answer=answer,explanation=explanation)
 if code:d['code']=code
 return d
add('Chapter roadmap','From bits to decisions','Five topics. One goal: turn a problem into clear, working instructions.','1–36','review',cards=[c('01 · Binary numbers','Represent numbers and pictures using just 0 and 1.'),c('02 · Variables & assignments','Store, update and display data. Choose a suitable data type.'),c('03 · Mathematical expressions','Write algorithms and calculate with the correct order of operations.'),c('04 · Strings','Join text and retrieve parts using indexes and substrings.'),c('05 · Boolean expressions','Compare values and combine conditions to make decisions.')],note='Each topic has four slides: understand the idea, explore it, apply it, and practise. Use the topic menu to jump to a section.')
add('1.1 · Binary numbers','Two digits. Endless possibilities.','A binary digit is a bit. Its value is either 0 or 1.','1–5','binary',cards=[c('Decimal · base 10','Uses digits 0–9. Place values are powers of 10: 1, 10, 100, …'),c('Binary · base 2','Uses digits 0 and 1. Place values are powers of 2: 1, 2, 4, 8, …'),c('Read the place values','110011₂ = 32 + 16 + 0 + 0 + 2 + 1 = 51₁₀.')],codeLabel='PLACE VALUE',code='Bit:       1   1   0   0   1   1\nPower:     5   4   3   2   1   0\nWeight:   32  16   8   4   2   1',practices=[q('What is 101010₂ in decimal?','42₁₀','Add the weights of the 1 bits: 32 + 8 + 2 = 42.'),q('What is 10111101₂ in decimal?','189₁₀','128 + 32 + 16 + 8 + 4 + 1 = 189.')],note='A base label tells us how to interpret the digits. 10₂ means two; 10₁₀ means ten.')
add('1.1 · Binary numbers','Decimal → binary, one step at a time','Divide by 2, record the remainder, and repeat until the quotient is 0.','1–3','binary',cards=[c('Divide','345 ÷ 2 = 172 remainder 1. Continue dividing each quotient by 2.'),c('Read upwards','The last remainder is the first binary digit. Reading bottom to top gives 101011001₂.'),c('Check the answer','256 + 64 + 16 + 8 + 1 = 345.')],demo='binary',note='Explore the chapter example 345, or enter another whole number. Click “Next division” to reveal each stage.')
add('1.1 · Binary numbers','A picture can be a pattern of bits','One bit per pixel is enough when an image has exactly two colours.','4–5','binary',cards=[c('Choose a convention','The chapter uses 0 for a black square and 1 for a white square.'),c('Store row by row','The first row is 11100111. Each row contains eight bits.'),c('Reconstruct the image','Read each bit and colour the corresponding pixel. The same convention must be used to encode and decode.')],demo='pixels',note='The displayed 8 × 8 pattern reproduces the chapter activity. The 64-bit count describes the pixels only; a file may also store metadata.')
add('1.1 · Binary numbers','Binary challenge lab','Try the chapter’s conversions, then reveal the answer and reasoning.','1–5','binary',cards=[c('Decimal → binary','Repeated division by 2; read the remainders upwards.'),c('Binary → decimal','Multiply each bit by its place value, then add the products.'),c('Image → bits','Keep the colour convention and the row order consistent.')],practices=[q('Convert 8136₁₀ to binary.','1111111001000₂','8136 = 4096 + 2048 + 1024 + 512 + 256 + 128 + 64 + 8.'),q('Convert 53721₁₀ to binary.','1101000111011001₂','53721 = 32768 + 16384 + 4096 + 256 + 128 + 64 + 16 + 8 + 1.'),q('Convert 110011₂ to decimal.','51₁₀','32 + 16 + 2 + 1 = 51.'),q('Encode the first picture row: white, white, white, black, black, white, white, white.','11100111','Apply the chapter convention: white = 1 and black = 0.')])
add('1.2 · Variables & assignments','Give your data a name','A variable is a named place to store a value that can be updated.','6–10','variables',cards=[c('Number','For calculations: bookPages = 301 and bookPrice = 38.'),c('String','For text: bookName = "Basic Physics" and bookAuthor = "Karl F. Kuhn".'),c('Boolean','For a true/false state: bookIsAvailable = true.')],code='let bookName = "Basic Physics";\nlet bookPages = 301;\nlet bookPrice = 38;\nlet bookIsAvailable = true;\n// Comments explain code; they are not executed.\nconsole.log(bookName);',practices=[q('Choose types for playerName and playerScore.','playerName: String\nplayerScore: Number','A name is text. A score must support numeric calculations.'),q('Is "301" the same type as 301?','No. "301" is a string; 301 is a number.','Quotation marks create text. Convert numeric input before calculating.')],note='Use meaningful names. In JavaScript, let declares a variable; = assigns a value; // starts a single-line comment.')
add('1.2 · Variables & assignments','Trace the changing values','Statements execute in sequence. A later assignment replaces the earlier value.','7–9','variables',codeLabel='PSEUDOCODE',code='x ← 5\ny ← 10\nz ← x\ny ← z\nDISPLAY(y)\nDISPLAY(x)\nDISPLAY(z)',demo='trace',note='The chapter’s output is 5, 5, 5. The arrow ← means assignment in pseudocode; JavaScript uses =.')
add('1.2 · Variables & assignments','Input → store → display','Collect the six contestants’ names and scores, then print their results.','9–12','variables',cards=[c('Pseudocode','DISPLAY a prompt → INPUT a value → assign it to a variable → DISPLAY the result.'),c('JavaScript input','prompt() returns text, or null if cancelled. Number() converts numeric text; validate it in a complete app.'),c('Six contestants','Repeat the same input/output pattern for players 1–6: Jon 50, Han 65, Tina 70, Rick 42, Nora 55, Alia 62.')],code='// Pattern for player 1; repeat for players 2–6.\nlet playerName1 = prompt("Enter player 1 name:");\nlet playerScore1 = Number(prompt("Enter score:"));\nconsole.log(playerName1 + " scored "\n  + playerScore1 + " points");',output='Jon scored 50 points',practices=[q('How should a Yes/No availability input become a Boolean?','let answer = prompt("Available? Yes/No");\nlet bookIsAvailable = answer?.toLowerCase() === "yes";','The input "Yes" is text. An explicit comparison produces true or false.'),q('Write pseudocode to collect a book’s name, author, pages and price.','bookName ← INPUT()\nbookAuthor ← INPUT()\nbookPages ← INPUT()\nbookPrice ← INPUT()','Display a clear prompt before each INPUT. Name and author are strings; pages and price are numbers.')])
add('1.2 · Variables & assignments','Predict before you run','Follow each assignment carefully. A copied value does not change automatically.','7–12','variables',cards=[c('Keep a trace table','Write each variable’s new value after every assignment.'),c('Display in order','Output depends on both the final values and the order of DISPLAY statements.'),c('Text and numbers','Joining text with + is concatenation in these examples.')],practices=[q('What are the four displayed names?','Han\nAmir\nAmir\nAmir','The first two DISPLAY statements run before student1 is assigned student2’s value.','student1 ← "Han"\nstudent2 ← "Amir"\nDISPLAY(student1)\nDISPLAY(student2)\nstudent1 ← student2\nDISPLAY(student1)\nDISPLAY(student2)'),q('Trace the chapter’s number-and-text example.','500HELLOPSEUDOCODE\nPSEUDOCODE\nPSEUDOCODE\nHELLO','After a ← c, a holds PSEUDOCODE. c ← b copies HELLO. b ← a copies PSEUDOCODE.','a ← 500\nb ← "HELLO"\nc ← "PSEUDOCODE"\nDISPLAY(a + b + c)\na ← c\nc ← b\nb ← a\nDISPLAY(a)\nDISPLAY(b)\nDISPLAY(c)'),q('Predict the master challenge output.','75\nGood\n100\n75','c becomes 75, d becomes 100, a becomes 75, c becomes 100, and d becomes 75.','a ← 25\nb ← "Good"\nc ← a * 3\nd ← a + c\na ← c\nc ← d\nd ← a\nDISPLAY(a)\nDISPLAY(b)\nDISPLAY(c)\nDISPLAY(d)')])
add('1.3 · Mathematical expressions','Turn a formula into an algorithm','An algorithm is an ordered set of steps for solving a problem.','13–14','math',cards=[c('Input','Get the parallelogram’s base and perpendicular height.'),c('Process','Multiply: area = base × height.'),c('Output','Display the area with square units, then end.')],codeLabel='PSEUDOCODE',code='START\nbase ← INPUT()\nheight ← INPUT()\narea ← base * height\nDISPLAY(area)\nEND',practices=[q('A parallelogram has base 12 cm and height 5 cm. Find its area.','60 cm²','12 × 5 = 60. Use perpendicular height, not the sloping side.'),q('Which arithmetic operators will you use?','+ add   - subtract   * multiply\n/ divide   % remainder   ** exponent','In pseudocode the remainder operator is often written MOD. JavaScript uses %.')])
add('1.3 · Mathematical expressions','Make the order work for you','Use parentheses to make an expression’s meaning clear.','13–16','math',cards=[c('PEMDAS','Parentheses → exponents → multiplication/division → addition/subtraction.'),c('Equal priority','Evaluate multiplication/division left to right. Do the same for addition/subtraction.'),c('JavaScript exponent','Write 4 ** 2 or Math.pow(4, 2). Do not use ^ for powers; it means bitwise XOR.')],demo='order',note='Example: 20 / 5 * 2 = 8, not 2. Parentheses can change the result: 20 / (5 * 2) = 2.')
add('1.3 · Mathematical expressions','Code that calculates','Apply formulas to circles and temperature conversion.','14–16','math',code='let radius = 50;\nlet circumference = 2 * 3.14 * radius;\nlet area = 3.14 * radius * radius;\nconsole.log(circumference, area);\n\nlet fahrenheit = 97;\nlet celsius = (fahrenheit - 32) * 5 / 9;\nconsole.log(celsius.toFixed(2));',output='Circumference: 314\nArea: 7850\nCelsius: 36.11',cards=[c('Circle','C = 2πr and A = πr². The chapter approximates π as 3.14.'),c('Temperature','C = (F − 32) × 5 / 9. Subtract 32 before multiplying and dividing.')],practices=[q('Convert 68°F to Celsius.','20°C','(68 − 32) × 5 / 9 = 36 × 5 / 9 = 20.'),q('For radius 10, find circumference and area using π = 3.14.','Circumference = 62.8\nArea = 314','2 × 3.14 × 10 and 3.14 × 10 × 10.')])
add('1.3 · Mathematical expressions','Solve the real-world challenges','Use the right formula, then check the units and rounding.','15–18','math',cards=[c('Compound growth','Amount = principal × (1 + rate / 100) ** years. Interest = amount − principal.'),c('Cookie pricing','Tax is 5% of $20 = $1. Add $6 shipping per box before multiplying by quantity.'),c('Money display','Use toFixed(2) when presenting currency; it returns formatted text.')],practices=[q('Find the interest on $5000 at 3% per year for three years.','$463.64 interest\n$5463.64 final amount','5000 × 1.03³ = 5463.635. Subtract 5000, then round for display.','let amount = 5000 * (1 + 3 / 100) ** 3;\nlet interest = amount - 5000;\nconsole.log(interest.toFixed(2));'),q('Four cookie boxes cost $20 each, with 5% tax and $6 shipping per box. What is the total?','$108','($20 + $1 + $6) × 4 = $108. Shipping is charged per box in the chapter.','basePrice ← 20\ntax ← 0.05 * basePrice\nshippingCost ← 6\nquantity ← 4\ntotalPrice ← (basePrice + tax + shippingCost) * quantity'),q('Predict: 2 + 3 * 4 and (2 + 3) * 4.','14 and 20','In the first expression multiplication happens first. Parentheses change the order in the second.'),q('Predict: 20 / 5 * 2 and 17 % 5.','8 and 2','Division and multiplication are evaluated left to right. 17 divided by 5 has remainder 2.')])
add('1.4 · Strings','Text is data too','A string is a sequence of characters enclosed in quotation marks.','19–21','strings',cards=[c('Characters','Letters, digits, spaces and punctuation can all be part of a string.'),c('Concatenation','Use + to join strings. Add spaces or separators explicitly.'),c('Numbers inside quotes','"235" + 2658 becomes "2352658". It joins text rather than adding numerically.')],code='let greeting = "Good " + "morning";\nlet address = "273-A" + " " + "William Street"\n  + " " + "Chicago" + " " + "United States of America";\nconsole.log(greeting);\nconsole.log(address);',practices=[q('Predict "235" + "256".','"235256"','Both operands are strings, so + concatenates them.'),q('Predict "Switch number-" + 265.','"Switch number-265"','The number is converted to text when joined to a string.'),q('Why does "Good" + "morning" look wrong?','It produces "Goodmorning". Add a space: "Good " + "morning".','Concatenation does not insert spaces automatically.')])
add('1.4 · Strings','Every character has a position','JavaScript indexes start at 0. A substring selects part of the text.','21, 25–26','strings',cards=[c('Index','word[0] is the first character. word[6] is the seventh character.'),c('Length','"PROGRAM".length is 7. Its last index is 6.'),c('Substring','substring(start, end) includes start and excludes end. substring(0, 4) retrieves four characters.')],demo='index',note='The chapter’s pseudocode SUBSTRING examples use 1-based positions with an inclusive end. JavaScript substring uses 0-based indexes with an excluded end. Keep the conventions separate.')
add('1.4 · Strings','Extract the useful pieces','Use known positions to retrieve structured parts of a string.','21, 24–26','strings',code='let iban = "FI087009010012345678901";\nconsole.log(iban.substring(4, 8));\nconsole.log(iban.substring(8, 23));\n\nlet product = "APPAREL_P001_XL_20134";\nconsole.log(product.substring(0, 7));\nconsole.log(product.substring(8, 12));\nconsole.log(product.substring(13, 15));\nconsole.log(product.substring(16));',output='Bank identifier: 7009\nAccount number: 010012345678901\nProduct parts: APPAREL · P001 · XL · 20134',practices=[q('Build a product ID from APPAREL, P020, M and 5623.','APPAREL_P020_M_5623','Join the four parts with underscores.','let category = "APPAREL";\nlet code = "P020";\nlet size = "M";\nlet id = 5623;\n// Write the expression for productID.'),q('Why should an account number usually remain text?','To preserve leading zeroes.','Converting "010012345678901" to a number loses its initial zero. It is an identifier, not a quantity.')],note='Fixed substring positions work for a known format. If part lengths vary, splitting on a separator is often safer.')
add('1.4 · Strings','Build names, addresses and email IDs','Practise joining text and selecting substrings from the chapter.','20–27','strings',cards=[c('Registration form','Collect firstName, lastName, grade, subjects and address. Join names with a space and display all details.'),c('Email pattern','userName + "@" + domainName constructs the chapter’s email example.'),c('Test separators','Check that spaces, @ and underscores appear in the right places.')],practices=[q('Create an email for Eva using the domain xyz.com.','let emailID = userName + "@" + domainName;\n// Output: Eva@xyz.com','The @ symbol must be inserted between the username and domain.','let userName = "Eva";\nlet domainName = "xyz.com";'),q('Build the registration output for Nora Smith, grade 12.','Name: Nora Smith\nGrade: 12\nSubjects: English, Science, Computer science\nAddress: 273-A William Street Chicago United States of America','fullName = firstName + " " + lastName. Keep the other fields in named variables.'),q('Build the address from the chapter’s four input fields.','273-A William Street Chicago United States of America','houseNo + " " + street + " " + city + " " + country. The spaces are part of the expression.'),q('What does "PROGRAM".substring(2, 5) return?','"OGR"','Select indexes 2, 3 and 4. Index 5 is excluded.')])
add('1.5 · Boolean expressions','Ask questions that have two answers','A Boolean expression evaluates to true or false.','28–29, 33','boolean',cards=[c('Relational operators','> greater, < less, >= at least, <= at most. JavaScript === tests equality and !== tests inequality.'),c('Assignment vs comparison','age = 18 assigns a value. age === 18 checks equality. Prefer strict equality in JavaScript.'),c('Threshold example','In the chapter’s hypothetical voting rule, eligible = age >= 18.')],code='let age = 23;\nlet eligible = age >= 18;\nconsole.log(eligible); // true\n\nlet num = 44;\nlet even = num % 2 === 0;\nlet positive = num > 0;',practices=[q('Using the chapter’s age rule, what happens at ages 17, 18 and 23?','false, true, true','The boundary is included because the test is >= 18.'),q('Is 0 positive? Is it even?','Positive: false\nEven: true','Positive means greater than 0. 0 % 2 is 0, so 0 is even.')],note='Pseudocode often uses = for equality and ← for assignment. JavaScript uses = for assignment and === for strict equality.')
add('1.5 · Boolean expressions','Combine conditions with logic','AND requires both; OR requires at least one; NOT reverses a Boolean value.','29–32','boolean',cards=[c('AND · &&','even && positive is true only when both conditions are true.'),c('OR · ||','even || positive is true when either condition, or both, are true.'),c('NOT · !','!true is false. De Morgan: !(P || Q) equals !P && !Q; !(P && Q) equals !P || !Q.')],demo='logic',note='For 44: AND true, OR true. For 77: AND false, OR true. For −22: AND false, OR true. For −15: both false.')
add('1.5 · Boolean expressions','Conditions that solve problems','Check divisibility, ranges and logical equivalence.','30–36','boolean',code='let num = 25;\nlet valid = num % 5 === 0 && num <= 30;\n\nlet number = 15;\nlet p = number % 3 !== 0;\nlet q = number % 5 !== 0;\nconsole.log(!(p || q) === (!p && !q));\n\nlet year = 2000;\nlet leap = (year % 4 === 0 && year % 100 !== 0)\n  || year % 400 === 0;',cards=[c('Remainder test','A multiple of 5 has remainder 0 when divided by 5. The printed MOD 5 = 10 is an error.'),c('Leap years','Divisible by 4, except century years must also be divisible by 400.'),c('Temperature bands','For whole-degree inputs: cold 0–20 inclusive; mild 21–30 inclusive; hot above 30.')],practices=[q('Check years 2001, 1900, 2000 and 2024.','2001: false\n1900: false\n2000: true\n2024: true','1900 fails the century exception; 2000 passes the divisibility-by-400 test.'),q('At temperature 25, what are cold, mild and hot?','cold: false\nmild: true\nhot: false','25 is between 21 and 30, inclusive. Use Number(input) before comparing.'),q('Is 25 a multiple of 5 that does not exceed 30?','true','25 % 5 === 0 and 25 <= 30 are both true.')],note='The temperature exercise uses whole degrees. For continuous readings, define the 20–21°C gap explicitly before implementing a complete classifier.')
add('1.5 · Boolean expressions','Predict, reverse and decide','Work through the chapter’s Boolean table and final challenges.','32–36','boolean',cards=[c('Evaluate inside out','Substitute the values, evaluate comparisons, then apply NOT, AND and OR.'),c('Palindrome','A number is a palindrome if its reversed digits equal the original number.'),c('Integer division','When extracting digits, discard the fractional part with Math.floor. The chapter’s plain division needs this clarification.')],practices=[q('For a = 10, b = 12, c = 8, evaluate the first four expressions.','1: false\n2: true\n3: true\n4: true','1 is false AND true. 2 is true OR true. 3 is NOT false AND true. 4 is false OR true.','1. (a > b) AND (a > c)\n2. (b > a) OR (b > c)\n3. NOT(a = b) AND (b > c)\n4. (a ≤ c) OR (b ≥ c)'),q('For a = 10, b = 12, c = 8, evaluate the last four expressions.','5: true\n6: true\n7: true\n8: true','5 negates a false conjunction. 6 has remainders 2 and 2. 7 negates false OR false. 8 combines 22 > 8 and 2 < 8.','5. NOT((a > b) AND (a < c))\n6. ((a MOD c) = 2) AND ((b MOD a) = 2)\n7. NOT((a = b) OR (b = c))\n8. (a + b > c) AND (b - a < c)'),q('Reverse 454 and check whether it is a palindrome.','Reverse = 454\nPalindrome = true','ones = 4, tens = 5, hundreds = 4. Use integer division when extracting digits.','let num = 454;\nlet ones = num % 10;\nlet tens = Math.floor(num / 10) % 10;\nlet hundreds = Math.floor(num / 100);\nlet reverse = ones * 100 + tens * 10 + hundreds;\nconsole.log(reverse, num === reverse);'),q('Does the same palindrome test pass for 123?','Reverse = 321\nPalindrome = false','The reverse differs from the original. This numeric method assumes a positive three-digit whole number.')])
add('Chapter review','You can now turn ideas into code','Connect the five topics in a final practice check.','1–36','review',cards=[c('Represent','Numbers and monochrome pixels can be encoded as bits.'),c('Store & calculate','Variables hold values; algorithms order the steps; expressions calculate results.'),c('Communicate & decide','Strings build useful output. Boolean expressions check conditions.')],practices=[q('A player scores 42. Show the score in binary, build a message and test whether it is even.','Binary: 101010₂\nMessage: Jon scored 42 points\nEven: true','42 = 32 + 8 + 2. Join the name and score with spaces. 42 % 2 === 0.'),q('A book costs $38. Two copies have 5% tax. Form a receipt message.','Subtotal: $76.00\nTax: $3.80\nMessage: Total: $79.80','38 × 2 = 76; 76 × 0.05 = 3.8; total = 79.8. Format with toFixed(2).'),q('Explain the difference between =, === and + in JavaScript.','= assigns; === compares; + adds numbers or joins strings.','The operand types determine whether + performs numeric addition or string concatenation.')],note='End of Chapter 1 · Explain your method, trace your values, and test boundary cases.')
imports=["import { Slide01Title } from './Slide01Title'"]
entries=["  { id: 'title', component: Slide01Title, label: 'Programming Basics', topic: 'Cover' },"]
for i,data in enumerate(slides,2):
 name=f'Slide{i:02d}'
 Path(f'src/slides/{name}.tsx').write_text("import { LessonSlide } from '@/components/lesson/LessonSlide'\nimport type { LessonData } from '@/components/lesson/LessonSlide'\n\nconst data: LessonData = "+json.dumps(data,ensure_ascii=False,indent=2)+f"\n\nexport function {name}() {{ return <LessonSlide data={{data}} /> }}\n",encoding='utf-8')
 imports.append(f"import {{ {name} }} from './{name}'")
 entries.append(f"  {{ id: 'slide-{i:02d}', component: {name}, label: {json.dumps(data['title'])}, topic: {json.dumps(data['topic'])} }},")
Path('src/slides/index.ts').write_text('\n'.join(imports)+'\n\nexport const SLIDES = [\n'+'\n'.join(entries)+'\n]\n',encoding='utf-8')
Path('CHAPTER_COVERAGE.md').write_text('# Chapter 1 coverage\n\nSource: C:/Users/Hp/Downloads/ch_1_A.pdf (36 scanned PDF pages; printed pages 18–53).\n\nThe attachment begins with binary activity solutions; the missing earlier introduction is supported with standard binary definitions. Teacher setup and external QR download instructions are not lesson content.\n\n'+ '\n'.join(f'- Slide {i:02d}: {d["title"]} — {d["topic"]}; PDF pages {d["pages"]}.' for i,d in enumerate(slides,2))+'\n\nCorrections: MOD 5 must equal 0, not 10; JavaScript indexes start at 0 and substring excludes end; digit extraction requires integer division; positive means > 0; Boolean availability requires converting Yes/No text; temperature intervals in source assume whole degrees. Money is rounded for display.\n',encoding='utf-8')
print(f'Created {len(slides)+1} slides including cover.')
